/**
 * Name search for the chore icon picker. Entries come from emoji-data.json
 * (generated by scripts/build-emoji.mjs): [emoji, CLDR label, space-separated tags].
 */
export type EmojiEntry = readonly [emoji: string, label: string, tags: string];

/** Typed or pasted text that is itself an emoji (offered as-is). */
export function looksLikeEmoji(s: string): boolean {
  return /\p{Extended_Pictographic}|\p{Regional_Indicator}/u.test(s);
}

const words = (s: string) => s.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean);

/**
 * Every query word must prefix a word of the label or tags. Ranked: exact
 * label, then all words matching the label, then tag-only matches; ties keep
 * the dataset's (Unicode) order.
 */
export function searchEmoji(entries: readonly EmojiEntry[], query: string, limit = 64): string[] {
  const q = words(query);
  if (q.length === 0) return [];
  const qJoined = q.join(" ");
  const scored: { emoji: string; rank: number; i: number }[] = [];
  entries.forEach(([emoji, label, tags], i) => {
    const lw = words(label);
    const all = lw.concat(words(tags));
    if (!q.every((w) => all.some((x) => x.startsWith(w)))) return;
    const rank = lw.join(" ") === qJoined ? 0 : q.every((w) => lw.some((x) => x.startsWith(w))) ? 1 : 2;
    scored.push({ emoji, rank, i });
  });
  scored.sort((a, b) => a.rank - b.rank || a.i - b.i);
  return scored.slice(0, limit).map((s) => s.emoji);
}
